function isBalanced(text) {
  const pairs = { ')': '(', ']': '[', '}': '{' }
  const stack = [] //@init
  for (const ch of text) { //@loop
    if (!(ch in pairs)) { stack.push(ch); continue } //@push
    if (stack.pop() !== pairs[ch]) return false //@pop
  }
  return stack.length === 0 //@done
}

