    stack = []  # openers still waiting for a closer
    for ch in text:
        if ch not in pairs:
            stack.append(ch)  # an opener: remember it
        elif not stack or stack.pop() != pairs[ch]:
            return False  # nothing to close, or the wrong opener on top
    return not stack  # every opener must be closed

