function solve(text: string): boolean {
  const pairs: Record<string, string> = { ')': '(', ']': '[', '}': '{' } // closer -> its opener
  const stack: string[] = [] // openers still waiting for a closer
  for (const ch of text) {
    if (!(ch in pairs)) stack.push(ch) // an opener: remember it
    else if (stack.pop() !== pairs[ch]) return false // nothing to close, or the wrong opener on top
  }
  return stack.length === 0 // every opener must be closed
}

